<?php $search=trim((string)($_GET['q'] ?? '')); $rows=query('SELECT id,full_name,jersey_number,birth_year,photo_path FROM players WHERE is_active=1 AND (full_name LIKE ? OR jersey_number LIKE ?) ORDER BY jersey_number',['%'.$search.'%','%'.$search.'%']); ?>
<div class="section-heading"><h2>The squad <span class="count-pill"><?= count($rows) ?></span></h2><form method="get" class="search-form"><input type="hidden" name="page" value="players"><input class="form-control" name="q" value="<?= e($search) ?>" placeholder="Search name or jersey" aria-label="Search players"><button class="btn btn-dark">Search</button></form></div>
<div class="squad-grid"><?php foreach($rows as $p): ?><a class="squad-card" href="<?= url('profile',['id'=>$p['id']]) ?>"><div class="squad-top"><span class="squad-number"><?= e($p['jersey_number']) ?></span><span class="squad-arrow">↗</span><?= avatar($p) ?></div><div class="squad-info"><small>SỐ ÁO <?= e($p['jersey_number']) ?></small><h2><?= e($p['full_name']) ?></h2><span>Viet Montreal United</span></div></a><?php endforeach; ?></div><?php if(!$rows): ?><div class="panel empty">Không tìm thấy cầu thủ.</div><?php endif; ?>
